// Original 8-bit style sound effects (generated by scripts/dev/make-sounds.mjs — no third-party audio).
// expo-audio is loaded lazily: on an APK without the native module, sounds are silently off (no crash).
import { requireOptionalNativeModule } from 'expo';
import type { AudioPlayer } from 'expo-audio';

import { usePrefs } from '../store/prefs';

export type SoundName = 'open' | 'shutter' | 'catch' | 'new' | 'rare' | 'shiny' | 'levelup' | 'reject';

const SOURCES: Record<SoundName, number> = {
  open: require('../../assets/sounds/open.wav'),
  shutter: require('../../assets/sounds/shutter.wav'),
  catch: require('../../assets/sounds/catch.wav'),
  new: require('../../assets/sounds/new.wav'),
  rare: require('../../assets/sounds/rare.wav'),
  shiny: require('../../assets/sounds/shiny.wav'),
  levelup: require('../../assets/sounds/levelup.wav'),
  reject: require('../../assets/sounds/reject.wav'),
};

type ExpoAudio = typeof import('expo-audio');
let audio: ExpoAudio | null | undefined;
const players: Partial<Record<SoundName, AudioPlayer>> = {};

function lib(): ExpoAudio | null {
  if (audio !== undefined) return audio;
  // Check first: requiring expo-audio without its native module raises a fatal module-init error.
  if (!requireOptionalNativeModule('ExpoAudio')) {
    audio = null; // older dev build without the audio module → sounds off, no error
    return audio;
  }
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    audio = require('expo-audio') as ExpoAudio;
    audio.setAudioModeAsync({ playsInSilentMode: false, shouldPlayInBackground: false, interruptionMode: 'mixWithOthers' }).catch(() => {});
  } catch {
    audio = null; // native module missing (older dev build)
  }
  return audio;
}

export function playSound(name: SoundName): void {
  if (!usePrefs.getState().soundsEnabled) return;
  const a = lib();
  if (!a) return;
  try {
    let p = players[name];
    if (!p) {
      p = a.createAudioPlayer(SOURCES[name]);
      p.volume = 0.7;
      players[name] = p;
    }
    p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // never let a sound break the flow
  }
}
